#include <iostream>
#include <vector>
#include <string_view>

void merge(std::vector<int>& arr, size_t low, size_t mid, size_t high) {
    std::vector<int> combined;
    combined.reserve(high - low + 1);

    size_t left = low;
    size_t right = mid + 1;

    while (left <= mid && right <= high) {
        if (arr[left] <= arr[right]) {
            combined.push_back(arr[left++]);
        } else {
            combined.push_back(arr[right++]);
        }
    }

    while (left <= mid) {
        combined.push_back(arr[left++]);
    }
    while (right <= high) {
        combined.push_back(arr[right++]);
    }

    for (size_t i = 0; i < combined.size(); ++i) {
        arr[low + i] = combined[i];
    }
}

void mergeSort(std::vector<int>& arr, size_t low, size_t high) {
    if (low >= high) {
        return; // Base case: 1 element
    }
    size_t mid = low + (high - low) / 2;
    mergeSort(arr, low, mid);
    mergeSort(arr, mid + 1, high);
    merge(arr, low, mid, high);
}

int main() {
    std::vector<int> data{37, 2, 6, 4, 89, 8, 10, 12, 68, 45};
    mergeSort(data, 0, data.size() - 1);

    for (size_t i = 0; i < data.size(); ++i) {
        std::cout << data[i] << (i + 1 == data.size() ? "" : " ");
    }
    std::cout << "\n";
    return 0;
}

#include <iostream>
#include <iomanip>
#include <cmath>

int main() {
    const long long n_values[] = {1024, 1048576}; // 2^10 and 2^20

    std::cout << "n          log2(n)    n*log2(n)       n^2 (approx)\n";
    std::cout << "--------------------------------------------------\n";

    for (long long n : n_values) {
        double logVal = std::log2(static_cast<double>(n));
        double nLogVal = n * logVal;
        double nSquared = static_cast<double>(n) * static_cast<double>(n);

        std::cout << std::left << std::setw(11) << n
                  << std::setw(11) << static_cast<long long>(logVal)
                  << std::setw(16) << static_cast<long long>(nLogVal)
                  << std::scientific << std::setprecision(2) << nSquared
                  << std::defaultfloat << "\n";
    }
    return 0;
}
